//
// Perform segmentation of MERSCOPE TIFF images using the vizgen-postprocessing tool
//

include { VIZGENPOSTPROCESSING_PREPARESEGMENTATION     } from 'nf-core/vizgenpostprocessing/preparesegmentation'
include { VIZGENPOSTPROCESSING_RUNSEGMENTATIONONTILE   } from 'nf-core/vizgenpostprocessing/runsegmentationontile'
include { VIZGENPOSTPROCESSING_COMPILETILESEGMENTATION } from 'nf-core/vizgenpostprocessing/compiletilesegmentation'

workflow TIFF_SEGMENTATION_VPT {

    take:
    ch_input             // channel: [ meta, image_dir, micron_to_mosaic_pixel_transform.csv ]
    ch_algorithm_json    // channel: [ algorithm.json ]
    ch_images_regex      // channel: [ val(regex) ]
    ch_custom_weights    // channel: [ custom_weights ]

    main:
    //
    // Generate segmentation parameters file
    //
    VIZGENPOSTPROCESSING_PREPARESEGMENTATION (
        ch_input,
        ch_algorithm_json,
        ch_images_regex
    )

    // Create list sequence of 0..N tiles
    // Get N from segmentation params JSON file
    VIZGENPOSTPROCESSING_PREPARESEGMENTATION.out.segmentation_files
        .map { _meta, seg_params -> seg_params }
        .splitJson(path: 'window_grid' )
        .filter { index -> index.key == 'num_tiles' }
        .map { index -> index.value.toInteger() }
        .flatMap { num -> (0..num-1).toList() }
        .set{ ch_tiles }

    // Create channel containing required segmentation files
    VIZGENPOSTPROCESSING_PREPARESEGMENTATION.out.segmentation_files
        .join(ch_input, by: 0)
        .map { meta, seg_params, image_dir, _pixel_file ->
            tuple(meta, image_dir, seg_params)
        }
        .set { ch_segmentation_files }

    //
    // Run vpt segmentation on each tile
    //
    VIZGENPOSTPROCESSING_RUNSEGMENTATIONONTILE(
        ch_segmentation_files.combine(ch_tiles),
        ch_algorithm_json,
        ch_custom_weights
    )

    /// collect segmented tiles
    VIZGENPOSTPROCESSING_RUNSEGMENTATIONONTILE.out.segmented_tile
        .map { _meta, seg_tile -> seg_tile }
        .flatten()
        .collect()
        .set{ ch_segmented_tiles }

    //
    // Compile segmentation results from all tiles
    //
    VIZGENPOSTPROCESSING_COMPILETILESEGMENTATION(
        ch_segmentation_files,
        ch_algorithm_json,
        ch_segmented_tiles
    )

    // Output channels for segmentations
    ch_micron_space_parquet =
        VIZGENPOSTPROCESSING_COMPILETILESEGMENTATION.out.micron_space
    ch_mosaic_space_parquet =
        VIZGENPOSTPROCESSING_COMPILETILESEGMENTATION.out.mosaic_space

    emit:
    micron_space_segmentation       = ch_micron_space_parquet  // channel: [ meta, parquet ]
    mosaic_space_segmentation       = ch_mosaic_space_parquet  // channel: [ meta, parquet ]
}

nextflow_workflow {

    name "Test Subworkflow TIFF_SEGMENTATION_VPT"
    script "../main.nf"
    workflow "TIFF_SEGMENTATION_VPT"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/tiff_segmentation_vpt"

    tag "vizgenpostprocessing/preparesegmentation"
    tag "vizgenpostprocessing/runsegmentationontile"
    tag "vizgenpostprocessing/compiletilesegmentation"

    config "./nextflow.config"

    test("merscope - tiff") {
        def images_dir
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            images_dir = extract(modules_testdata_base_path + 'spatial_omics/merscope/minimal_data.tar.gz').resolve('minimal_data/images')
        }

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test' ],
                    file('${images_dir}'),
                    file('${images_dir}/micron_to_mosaic_pixel_transform.csv')
                ])
                // file cannot be hosted in the nf-core test-datasets repo due to licensing issues
                input[1] = file('https://raw.githubusercontent.com/Vizgen/vpt-plugin-cellpose2/refs/heads/develop/example_analysis_algorithm/cellpose2_nuclei.json', checkIfExists: true) // Algorithm JSON
                input[2] = "mosaic_(?P<stain>[\\\\w|-]+)_z(?P<z>[0-9]+).tif" // Image regex
                input[3] = [] // No custom weights
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    sanitizeOutput(workflow.out, unstableKeys: ["micron_space_segmentation", "mosaic_space_segmentation"])
                ).match() }
            )
        }
    }
}
